import { createElement, render } from 'preact';
import { setupScratch, teardown } from '../../../test/_util/helpers';
import { useErrorBoundary, useState } from 'preact/hooks';
import { setupRerender } from 'preact/test-utils';
import { Component } from 'preact';

/** @jsx createElement */

describe('tmp debug', () => {
	let scratch, rerender;

	beforeEach(() => {
		scratch = setupScratch();
		rerender = setupRerender();
	});

	afterEach(() => {
		teardown(scratch);
	});

	const baseTodos = [
		{ text: 'first item', completed: false },
		{ text: 'Test the feature', completed: false },
		{ text: 'another item', completed: false }
	];

	function makeList(Item) {
		function TodoList() {
			const [todos, setTodos] = useState([...baseTodos]);
			return (
				<ul>
					{todos.map((todo, index) => (
						<Item
							key={index}
							toggleTodo={() => {
								todos[index] = {
									...todos[index],
									completed: !todos[index].completed
								};
								setTodos([...todos]);
							}}
							todo={todo}
							index={index}
						/>
					))}
				</ul>
			);
		}
		return TodoList;
	}

	function TodoItemInner({ todo, index, toggleTodo }) {
		if (todo.completed) {
			throw new Error('Todo completed!');
		}
		if (index === 1) {
			set = toggleTodo;
		}
		return (
			<li>
				<label>
					<input type="checkbox" checked={todo.completed} onInput={toggleTodo} />
					{todo.completed ? <s>{todo.text}</s> : todo.text}
				</label>
			</li>
		);
	}

	let set;

	it('class boundary', () => {
		class TodoItem extends Component {
			componentDidCatch() {
				this.setState({});
			}
			render(props) {
				if (this.state.errored) {
					return <li>An error occurred: {this.state.errored}</li>;
				}
				return <TodoItemInner {...props} />;
			}
		}
		set = null;
		render(<div />, scratch);
		const List = makeList(TodoItem);
		render(<List />, scratch);
		console.log('initial:', scratch.innerHTML);
		set();
		rerender();
		console.log('after class:', scratch.innerHTML);
	});

	it('hooks boundary', () => {
		set = null;
		function TodoItem(props) {
			const [error] = useErrorBoundary();
			if (error) {
				return <li>An error occurred: {error}</li>;
			}
			return <TodoItemInner {...props} />;
		}
		const List = makeList(TodoItem);
		render(<List />, scratch);
		console.log('initial:', scratch.innerHTML);
		set();
		rerender();
		console.log('after hooks:', scratch.innerHTML);
	});
});

